function ResearchMarkdown({text}:{text:string}){
 const inline=(value:string)=>value.split(/(\*\*[^*]+\*\*|`[^`]+`|\[[^\]]+\]\(https:\/\/[^)\s]+\))/g).map((part,index)=>{
  if(part.startsWith('**')&&part.endsWith('**'))return <strong key={index}>{part.slice(2,-2)}</strong>;
  if(part.startsWith('`')&&part.endsWith('`'))return <code key={index}>{part.slice(1,-1)}</code>;
  const link=part.match(/^\[([^\]]+)\]\((https:\/\/[^)\s]+)\)$/);if(link)return <a key={index} href={link[2]} target="_blank" rel="noreferrer">{link[1]} <ExternalLink size={10}/></a>;
  return part;
 });
 const lines=text.split(/\r?\n/);const blocks:React.ReactNode[]=[];let i=0;
 while(i<lines.length){const line=lines[i].trim();if(!line){i++;continue;}
  if(line.startsWith('|')){const rows:string[][]=[];while(i<lines.length&&lines[i].trim().startsWith('|')){rows.push(lines[i].trim().replace(/^\||\|$/g,'').split('|').map(cell=>cell.trim()));i++;}const tableRows=rows.filter(row=>!row.every(cell=>/^:?-{3,}:?$/.test(cell)));if(tableRows.length)blocks.push(<div className="markdown-table-wrap" key={`table-${i}`}><table><thead><tr>{tableRows[0].map((cell,j)=><th key={j}>{inline(cell)}</th>)}</tr></thead><tbody>{tableRows.slice(1).map((row,j)=><tr key={j}>{row.map((cell,k)=><td key={k}>{inline(cell)}</td>)}</tr>)}</tbody></table></div>);continue;}
  const heading=line.match(/^(#{1,3})\s+(.+)/);if(heading){const Tag=`h${heading[1].length+2}` as 'h3'|'h4'|'h5';blocks.push(<Tag key={`heading-${i}`}>{inline(heading[2])}</Tag>);i++;continue;}
  if(/^[-*]\s+/.test(line)||/^\d+\.\s+/.test(line)){const numbered=/^\d+\.\s+/.test(line);const items:string[]=[];while(i<lines.length&&(/^[-*]\s+/.test(lines[i].trim())||/^\d+\.\s+/.test(lines[i].trim()))){items.push(lines[i++].trim().replace(/^([-*]|\d+\.)\s+/,''));}const List=numbered?'ol':'ul';blocks.push(<List key={`list-${i}`}>{items.map((item,j)=><li key={j}>{inline(item)}</li>)}</List>);continue;}
  const paragraph=[line];i++;while(i<lines.length&&lines[i].trim()&&!/^(#{1,3})\s|^[-*]\s|^\d+\.\s|^\|/.test(lines[i].trim()))paragraph.push(lines[i++].trim());blocks.push(<p key={`paragraph-${i}`}>{inline(paragraph.join(' '))}</p>);
 }
 return <div className="markdown-response">{blocks}</div>;
}
